"""Ask Atlas curated answers. Every fact here also appears, with sources, in the linked guide."""
QA = [
 (["watch", "warning", "difference", "advisory"], "What's the difference between a watch and a warning?",
  "A <b>watch</b> means conditions are favorable, so be prepared. A <b>warning</b> means the hazard is happening or about to happen, so take action now. An <b>advisory</b> is a less serious hazard that still calls for caution.", "watch-vs-warning"),
 (["tornado", "shelter", "basement", "mobile home"], "Where should I shelter from a tornado?",
  "Go to a basement, storm cellar or the lowest floor of a sturdy building. With no basement, use a small interior room with no windows, such as a closet, a bathroom or an interior hallway, and cover your head and neck. Mobile homes don't offer protection.", "tornado-watch-vs-warning"),
 (["lightning", "thunder", "outside", "how long", "30"], "How long should I wait after thunder?",
  "When thunder roars, go indoors. Lightning can strike as far as 10 miles from a storm. Stay inside until 30 minutes after the last thunder you hear.", "lightning-safety"),
 (["lightning", "car", "tent", "shelter", "safe"], "Is a tent or picnic shelter safe from lightning?",
  "No. Safe shelter is a substantial building with wiring and plumbing, or a hard-topped metal vehicle with the windows up. Tents, picnic shelters and open-sided structures don't protect you.", "lightning-safety"),
 (["severe", "thunderstorm", "hail", "58", "mph"], "What makes a thunderstorm 'severe'?",
  "NWS calls a thunderstorm severe when it has hail 1 inch or larger, wind gusts of 58 mph or more, or a tornado.", "thunderstorm-lightning-safety"),
 (["flood", "water", "drive", "road", "car", "inches"], "How much water can sweep away a car?",
  "12 inches of moving water can carry away most cars, and 2 feet can carry away SUVs and trucks. Just 6 inches of fast-moving water can knock an adult off their feet. Turn Around, Don't Drown.", "flood-safety-turn-around"),
 (["hurricane", "category", "saffir", "simpson", "scale"], "What do hurricane categories mean?",
  "On the Saffir-Simpson scale: Category 1 is 74–95 mph, 2 is 96–110, 3 is 111–129, 4 is 130–156, and 5 is 157 mph or higher. Categories 3–5 are 'major'. The scale covers wind only, not surge or flooding.", "hurricane-preparedness"),
 (["hurricane", "watch", "warning", "hours", "36", "48"], "When are hurricane watches and warnings issued?",
  "A hurricane watch is issued 48 hours before tropical-storm-force winds are expected; a warning, 36 hours before.", "hurricane-preparedness"),
 (["hurricane", "season", "when", "june", "november"], "When is hurricane season?",
  "The Atlantic season runs from June 1 to November 30. The eastern Pacific season starts May 15.", "hurricane-preparedness"),
 (["cone", "track", "hurricane"], "Am I safe if I'm outside the hurricane cone?",
  "Not necessarily. The cone shows the probable track of the storm's <i>center</i>. Surge, heavy rain and wind often reach far outside it.", "hurricane-preparedness"),
 (["radar", "colors", "dbz", "red", "purple", "magenta"], "What do the radar colors mean?",
  "Colors show reflectivity in dBZ. Greens are light rain, yellow and orange are heavier rain, red is very heavy rain, and magenta, purple or white often means hail. Color scales vary between apps.", "how-to-read-weather-radar"),
 (["hook", "echo", "bow", "radar", "rotation"], "What's a hook echo or a bow echo?",
  "A hook echo is a hook shape on the back of a supercell that can indicate rotation and a possible tornado. A bow echo is a bulging line of storms that often brings damaging straight-line winds.", "how-to-read-weather-radar"),
 (["pressure", "barometer", "falling", "rising", "inhg", "hpa"], "What does falling pressure mean?",
  "Steadily falling pressure often means an approaching low and worsening weather. Rising pressure often means clearing. Standard sea-level pressure is 29.92 inHg (1013.25 hPa).", "barometric-pressure-and-weather"),
 (["kit", "emergency", "water", "gallon", "supplies", "outage"], "What goes in an emergency kit?",
  "Ready.gov's basics: one gallon of water per person per day for several days, non-perishable food, a battery or hand-crank radio, a flashlight, a first-aid kit, extra batteries, a whistle, chargers and a backup battery, plus medicines and copies of documents.", "weather-emergency-kit"),
 (["no signal", "off-grid", "offgrid", "satellite", "backcountry", "noaa radio", "weather radio"], "How do I get warnings with no cell signal?",
  "Carry a NOAA Weather Radio: it broadcasts NWS warnings 24/7 on 162.400–162.550 MHz and needs no cell signal. Some newer phones can text by satellite. In the app, Off-Grid Safety (free) helps you text your saved location to emergency contacts. Carrier message and data rates may apply.", "off-grid-emergency-weather"),
]
